/**
 * The guide in the active language.
 *
 * A function rather than a `val`: the words come from resources, so they have to be read
 * inside composition. Reading them once into a top-level `val` would freeze whichever
 * locale happened to be current when the class was first touched, and the in-app language
 * picker would stop working for this screen.
 */
@Composable
fun helpTopics(): List<HelpTopic> {
    require(TOPICS.size == ENTRIES.size) {
        "help guide: ${TOPICS.size} topics but ${ENTRIES.size} entry lists"
    }
    return TOPICS.zip(ENTRIES) { (titleRes, introRes), pairs ->
        HelpTopic(
            title = stringResource(titleRes),
            intro = stringResource(introRes),
            entries = pairs.map { (labelRes, bodyRes) ->
                HelpEntry(stringResource(labelRes), stringResource(bodyRes))
            },
        )
    }
}
